  groupByQstn(qstnList) {
    var helper = {};
    this.qstnArray.push(qstnList.reduce(function (r, o) {
      var key = o.domain_id + '-' + o.skills + '-' + o.sub_skills;
      if (!helper[key]) {
        helper[key] = Object.assign({}, o); // create a copy of o
        r.push(helper[key]);
      } else {
        helper[key].used += o.used;
        helper[key].instances += o.instances;
      }

      return r;
    }, []));
  }

  //set form values for yearly leaves
  domainFormDetails() {
    this.countVal = 0;
    this.assessmentList = [];
    this.qstnArray = [];
    (this.interventionForm.controls.headingAry as FormArray).clear();
    this.assessmentList = this.interventionForm.controls.headingAry as FormArray;
    debugger
    for (let i = 0; i < this.domainArray.length; i++) {
      let qstnIndex = [];
      let finalInterVen = [];
      let choiceInt: any = [...new Map(this.domainArray[i].intervenList.map(item => [item['choice_intervension'], item])).values()];
      for (let j = 0; j < choiceInt.length; j++) {
        if (choiceInt[j].choice_intervension > 0) {
          this.interVenList.forEach(ele => {
            ele.domain_id = cloneDeep(choiceInt[j].domain_id);
            ele.domain_name = cloneDeep(choiceInt[j].domain_name);
            if (choiceInt[j].choice_intervension == ele.intervention_type_id) {
              qstnIndex.push(cloneDeep(ele));
            }
          });
        }
      };

      setTimeout(() => { 

        this.assessmentList.push(
          this.formBuilder.group({
            domain_id: new FormControl(this.domainArray[i].domain_id, null),
            domain: new FormControl(this.domainArray[i].domain_name, null),
            subdomain_id: new FormControl(this.domainArray[i].subdomain_id, null),
            sub_domain: new FormControl(this.domainArray[i].sub_domain, null),
            questionAry: this.formBuilder.array([]),
            isHide: new FormControl(false)
          })
        );

        this.groupByQstn(qstnIndex);
        this.questionList = this.assessmentList.controls[i]['controls'].questionAry as FormArray;
        this.assessmentList.controls[i].patchValue({
          isHide: this.qstnArray[i].length > 0 ? false : true
        });

        this.domainArray[i].isHide = this.qstnArray[i].length > 0 ? false : true;
        if (!(this.interventionForm.value.headingAry[i].isHide)) {
          this.countVal = this.countVal + 1;
        }
        if (this.countVal == 0) {
          let stuQstnIndex = [];
          if (this.assStudDetails.length > 0) {
            stuQstnIndex = this.assStudDetails.filter((key) => key.user_id == this.user_id && key.stud_id == this.studId);
          } else {
            stuQstnIndex = [];
          }
          if (stuQstnIndex.length > 0) {
            if (stuQstnIndex[0].support != '' && stuQstnIndex[0].support != null && stuQstnIndex[0].support != 0) {
              this.interventionForm.controls['support'].setValue(stuQstnIndex[0].support);
            } else {
              this.interventionForm.controls['support'].setValue(5);
            }
          } else {
            this.interventionForm.controls['support'].setValue(5);
          }
          this.interventionForm.controls['support'].updateValueAndValidity();
        }

        for (let j = 0; j < this.qstnArray[i].length; j++) {
          this.assessmentList.controls[i]['controls']
          let question = this.qstnArray[i][j];
          let optnIndex = qstnIndex.filter((key) => key.domain_id == question.domain_id && (key.skills == question.skills && key.sub_skills == question.sub_skills));
          this.questionList.push(this.formBuilder.group({
            intervention_type_id: new FormControl(question.intervention_type_id, null),
            intervention_type: new FormControl(question.intervention_type, null),
            intervension: new FormControl(question.intervension, null),
            intervension_tamil: new FormControl(question.intervension_tamil, null),
            skills: new FormControl(question.skills, null),
            sub_skills: new FormControl(question.sub_skills, null),
            optionAry: this.formBuilder.array([]),
            isOpen: new FormControl(true)
          }));
          this.optionList = this.questionList.controls[j]['controls'].optionAry as FormArray;
          // for (let k = 0; k < optnIndex.length; k++) {
          for (let k = 0; k < optnIndex.length; k++) {
            let option = optnIndex[k];
            let stuQstnIndex = [];
            if (this.assStudDetails.length > 0) {
              stuQstnIndex = this.assStudDetails.filter((key) => key.user_id == this.user_id && key.stud_id == this.studId && key.intervension_idx_id == option.intervension_idx_id);
            } else {
              stuQstnIndex = [];
            }
            let indexId;
            let goalVal;
            let RateVal;

            if (stuQstnIndex.length > 0) {
              if (stuQstnIndex[0].support != '' && stuQstnIndex[0].support != null && stuQstnIndex[0].support != 0) {
                this.interventionForm.controls['support'].setValue(stuQstnIndex[0].support);
              } else {
                this.interventionForm.controls['support'].setValue('');
              }
              this.interventionForm.controls['support'].updateValueAndValidity();
              if (stuQstnIndex.length > 0) {
                indexId = stuQstnIndex[0].index_id;
                goalVal = parseInt(stuQstnIndex[0].goal_val);
                RateVal = stuQstnIndex[0].rate_val;
              } else {
                indexId = '';
                goalVal = false;
                RateVal = null;
              }
            } else {
              indexId = '';
              goalVal = false;
              RateVal = null;
            };
            this.optionList.push(this.formBuilder.group({
              index_id: new FormControl(indexId, null),
              intervension_idx_id: new FormControl(option.intervension_idx_id, null),
              intervention_type_id: new FormControl(option.intervention_type_id, null),
              intervention_type: new FormControl(option.intervention_type, null),
              goal: new FormControl(option.goal, null),
              goal_tamil: new FormControl(option.goal_tamil, null),
              rate_val: new FormControl(RateVal, Validators.required),
              goal_val_id: new FormControl(goalVal, null),
              goal_val: new FormControl(goalVal, null),
              inter_status: new FormControl(option.inter_status, null),
            }));
          }


          if (this.questionList.length > 0) {
            this.countVal = this.countVal + 1;
          }

        }
      }, 500)
    }
  }

